import copy,hashlib,json,sys
from pathlib import Path
root=Path('/home/josh/projects/klem');sys.path.insert(0,str(root/'tools'))
from doeda_native_corpora import words_from_cli
old=root/'web/test-results/degree-expectation-main-cargo/debug/klem'; new=Path('/tmp/klem-declarative-contrast-prototype-source-cli')
source=json.loads((root/'docs/literary-ri-prefinal-legacy-history.json').read_bytes())
output=Path('/tmp/klem-declarative-contrast-prototype-legacy-history.json');assert not output.exists()
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
sources={};origins={};fields={'before_words','before_analyses','source_before_analyses','source_cohort_before_analyses'}
def visit(v,path,pointer=''):
 if isinstance(v,dict):
  for key,item in v.items():
   at=pointer+'/'+key
   if key in fields and isinstance(item,dict):
    for surface in item:origins.setdefault(surface,[]).append({'source':path,'source_sha256':sources[path],'pointer':at})
   else:visit(item,path,at)
 elif isinstance(v,list):
  for i,item in enumerate(v):visit(item,path,pointer+'/'+str(i))
for name,h in source['source_files_sha256'].items():
 assert sha(root/name)==h; sources[name]=h; visit(json.loads((root/name).read_bytes()),name)
assert len(sources)==47 and len(origins)==21298
frozen={str(old):sha(old),str(new):sha(new)}
before=words_from_cli(old,sorted(origins));after=words_from_cli(new,sorted(origins));changes={};count=0
forms={'다만':('다','만'),'다마는':('다','마는'),'는다만':('는다','만'),'는다마는':('는다','마는')}
for word,b in before.items():
 a=after[word]
 assert {k:v for k,v in b.items() if k!='analyses'}=={k:v for k,v in a.items() if k!='analyses'}
 assert [p for p in a['analyses'] if p in b['analyses']]==b['analyses'],word
 if a==b:continue
 additions=[]
 for candidate in a['analyses']:
  if candidate in b['analyses']:continue
  assert 'ending.declarative_contrast' in candidate['rules'],(word,candidate)
  inverse=copy.deepcopy(candidate); positions=[]; morphs=[]; source_entries=[]
  for i,m in enumerate(inverse['morphemes']):
   if m['kind']=='ending' and m['form'] in forms:
    original=m['form']; plain,particle=forms[original]; positions.append(i)
    morphs.extend([dict(m,form=plain),{'form':particle,'kind':'particle'}])
    source_entries.extend({'다만':['krdict:80322'],'다마는':['krdict:80321'],'는다만':['krdict:80324','krdict:80326'],'는다마는':['krdict:80323','krdict:80325']}[original])
   else:morphs.append(m)
  assert positions
  inverse['morphemes']=morphs
  inverse['rules']=sorted(set(r for r in inverse['rules'] if r!='ending.declarative_contrast')|{'particle','particle.concessive'})
  for p in inverse.get('spelling_paths',[]):
   for recovery in p:recovery['morpheme_index']+=sum(i<recovery['morpheme_index'] for i in positions)
  assert inverse in b['analyses'],(word,'missing exact older split-particle parent',candidate,inverse)
  ident=hashlib.sha256(json.dumps([word,candidate],ensure_ascii=False,sort_keys=True).encode()).hexdigest()[:24]
  additions.append({'id':'declarative-contrast-legacy-'+ident,'analysis':candidate,'exact_split_particle_parent':inverse,'source_entries':sorted(set(source_entries)),'structural_verdict':'unjudged broader composition','contextual_verdict':'unjudged','independent_review':'pending'});count+=1
 changes[word]={'before':b,'after':a,'origins':origins[word],'additions':additions}
assert all(sha(root/n)==h for n,h in sources.items()) and all(sha(n)==h for n,h in frozen.items())
producer=Path(__file__)
r={'schema_version':1,'state':'complete-legacy-candidate-preservation-passed','source_files_sha256':sources,'before_cli_sha256':sha(old),'cli_sha256':sha(new),'surfaces':len(origins),'changed_words':len(changes),'added_paths':count,'changes':changes,'frozen_inputs':frozen,'inputs_unchanged':True,'producer':{'text':producer.read_text(),'sha256':sha(producer)},'scope':'Actual complete isolated replay of all 47 immutable historical source cohort files and all 21,298 distinct words. Every old candidate retains exact fields and relative order. Each new whole connective has a stable individual ID, original source pointer and byte-equivalent older split final-ending/particle parent on the same word. Additions remain structurally/contextually unjudged; no older judgment or capture is rewritten.','contextual_verdict':'unjudged','independent_review':'pending'}
output.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
print('Preserved all',len(origins),'actual prior words;',len(changes),'changed words;',count,'individually tracked whole connectives with exact older particle parents.',flush=True)
